WITH monthly AS (SELECT o.purchase_month AS month, SUM(o.items_revenue) AS revenue, COUNT(*) FILTER(WHERE o.is_sale) AS sale_orders, SUM(o.items_revenue) / NULLIF(COUNT(*) FILTER(WHERE o.is_sale AND o.item_count > 0), 0) AS avg_order_value FROM analytics.orders AS o WHERE o.purchase_month BETWEEN CAST('2017-01-01' AS DATE) AND CAST('2018-08-31' AS DATE) GROUP BY o.purchase_month), mar AS (SELECT * FROM monthly WHERE month = CAST('2018-03-01' AS DATE)), baseline AS (SELECT AVG(revenue) AS avg_revenue, AVG(sale_orders) AS avg_sale_orders, AVG(avg_order_value) AS avg_aov FROM monthly WHERE month <> CAST('2018-03-01' AS DATE)), mar_cat AS (SELECT oi.category, SUM(oi.price) AS revenue, COUNT(DISTINCT oi.order_id) AS orders FROM analytics.order_items AS oi WHERE oi.is_sale AND oi.purchase_month = CAST('2018-03-01' AS DATE) GROUP BY oi.category), feb_cat AS (SELECT oi.category, SUM(oi.price) AS revenue FROM analytics.order_items AS oi WHERE oi.is_sale AND oi.purchase_month = CAST('2018-02-01' AS DATE) GROUP BY oi.category) SELECT mar.month, ROUND(mar.revenue, 2) AS revenue, mar.sale_orders, ROUND(mar.avg_order_value, 2) AS avg_order_value, ROUND(b.avg_revenue, 2) AS baseline_avg_monthly_revenue, ROUND(b.avg_sale_orders, 2) AS baseline_avg_sale_orders, ROUND(b.avg_aov, 2) AS baseline_avg_order_value, ROUND(mar.revenue - b.avg_revenue, 2) AS revenue_gap_vs_baseline, ROUND(100.0 * (mar.revenue - b.avg_revenue) / NULLIF(b.avg_revenue, 0), 2) AS revenue_gap_pct FROM mar CROSS JOIN baseline AS b LIMIT 501
